import shutil
import openpyxl
from datetime import datetime, date

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Before"]
vws = vals["Before"]

def is_date_like(value):
    if isinstance(value, (datetime, date)):
        return True
    if isinstance(value, str):
        s = value.strip()
        if not s:
            return False
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d-%m-%Y",
            "%Y/%m/%d",
        ):
            try:
                datetime.strptime(s, fmt)
                return True
            except ValueError:
                pass
    return False

def to_date_value(value):
    if isinstance(value, datetime):
        return value
    if isinstance(value, date):
        return datetime(value.year, value.month, value.day)
    if isinstance(value, str):
        s = value.strip()
        for fmt in (
            "%Y-%m-%d %H:%M:%S",
            "%Y-%m-%d",
            "%m/%d/%Y %H:%M:%S",
            "%m/%d/%Y",
            "%d-%m-%Y",
            "%Y/%m/%d",
        ):
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                pass
    return value

updated = 0
unchanged = 0

for row in range(2, 20):
    g_val = vws.cell(row=row, column=7).value
    if is_date_like(g_val):
        ws.cell(row=row, column=11).value = to_date_value(g_val)
        updated += 1
    else:
        unchanged += 1

print("updated:", updated, "unchanged:", unchanged)
print("K2:", ws.cell(row=2, column=11).value)
print("K4:", ws.cell(row=4, column=11).value)
print("K14:", ws.cell(row=14, column=11).value)
print("K19:", ws.cell(row=19, column=11).value)

wb.save(OUT)
